export const constitution={"I":{"title":"Grundlagen und Grundrechte","articles":[{"number":1,"title":"Menschenwürde","text":"Jeder Mensch besitzt denselben unveräußerlichen menschlichen Wert. Staatliche und gesellschaftliche Einrichtungen dürfen Menschen nicht zum bloßen Mittel machen."},{"number":2,"title":"Gleichwertigkeit","text":"Unterschiede in Fähigkeiten, Herkunft, Lebensweg, Einkommen oder Beitrag begründen keinen unterschiedlichen menschlichen Wert."},{"number":3,"title":"Freiheit","text":"Jeder Mensch darf sein Leben nach eigenen Vorstellungen gestalten, soweit dadurch Rechte anderer nicht verletzt werden."},{"number":4,"title":"Verantwortung","text":"Freiheit und Verantwortung gehören zusammen. Wer Rechte ausübt, achtet die Rechte und die Sicherheit anderer."},{"number":5,"title":"Rechtsbindung","text":"Alle staatlichen Organe sind an diese Verfassung und das Gesetz gebunden."},{"number":6,"title":"Gesellschaftlicher Zweck","text":"Staatliche Einrichtungen dienen dem Schutz der Menschen, ihrer Rechte und der gemeinsamen Handlungsfähigkeit."},{"number":7,"title":"Vielfalt","text":"Unterschiedliche Lebensentwürfe, Fähigkeiten, Kulturen und Überzeugungen dürfen nebeneinander bestehen."},{"number":8,"title":"Gleichheit vor dem Recht","text":"Alle Menschen sind vor dem Gesetz gleich. Unterschiede bedürfen eines sachlichen und verhältnismäßigen Grundes."},{"number":9,"title":"Diskriminierungsverbot","text":"Benachteiligungen wegen persönlicher Merkmale sind unzulässig, soweit sie nicht zum Schutz gleichwertiger Rechte zwingend gerechtfertigt sind."},{"number":10,"title":"Meinungsfreiheit","text":"Jeder Mensch darf Meinungen äußern, verbreiten, kritisieren und ändern."},{"number":11,"title":"Informationsfreiheit","text":"Jeder Mensch hat grundsätzlich Zugang zu öffentlichen Informationen und zu den Grundlagen staatlicher Entscheidungen."},{"number":12,"title":"Versammlungsfreiheit","text":"Menschen dürfen sich friedlich und ohne Waffen versammeln."},{"number":13,"title":"Vereinigungsfreiheit","text":"Menschen dürfen Vereinigungen gründen, ihnen beitreten und sie verlassen."},{"number":14,"title":"Religionsfreiheit","text":"Jeder Mensch darf eine Religion ausüben, wechseln, ablehnen oder keiner Religion angehören."},{"number":15,"title":"Gewissensfreiheit","text":"Niemand darf wegen einer persönlichen Gewissensentscheidung staatlich benachteiligt werden, soweit dadurch Rechte anderer nicht verletzt werden."},{"number":16,"title":"Privatleben","text":"Das Privatleben, die Wohnung und persönliche Kommunikation stehen unter besonderem Schutz."},{"number":17,"title":"Körperliche Unversehrtheit","text":"Jeder Mensch hat Anspruch auf Schutz vor rechtswidriger Gewalt und Eingriffen in den eigenen Körper."},{"number":18,"title":"Persönliche Freiheit","text":"Freiheitsentzug ist nur aufgrund eines Gesetzes, eines rechtmäßigen Verfahrens und unter gerichtlicher Kontrolle zulässig."},{"number":19,"title":"Eigentum","text":"Eigentum wird geschützt und verpflichtet zugleich. Sein Gebrauch darf dem Schutz anderer und der Allgemeinheit nicht widersprechen."},{"number":20,"title":"Erbrecht","text":"Vermögen darf grundsätzlich vererbt werden, soweit besondere Regeln dieser Verfassung für gesellschaftlich gebundene Unternehmensrechte gelten."},{"number":21,"title":"Berufsfreiheit","text":"Jeder Mensch darf Beruf, Ausbildung und Erwerbsform grundsätzlich frei wählen."},{"number":22,"title":"Unternehmerische Freiheit","text":"Jeder darf im Rahmen des Rechts Unternehmen gründen, führen, verändern oder aufgeben."},{"number":23,"title":"Forschungsfreiheit","text":"Wissenschaftliche Forschung und Lehre sind frei, soweit sie Rechte anderer und geltendes Recht achten."},{"number":24,"title":"Kunstfreiheit","text":"Kunst und kulturelle Tätigkeit sind frei."},{"number":25,"title":"Pressefreiheit","text":"Journalistische Tätigkeit ist frei. Medien sollen ihre Finanzierung und wesentliche Interessenkonflikte offenlegen."},{"number":26,"title":"Quellenschutz","text":"Journalistische Quellen werden geschützt, soweit nicht ein überwiegendes gesetzliches Interesse nach gerichtlicher Prüfung entgegensteht."},{"number":27,"title":"Datenschutz","text":"Personenbezogene Daten dürfen nur zweckgebunden, nachvollziehbar und nach klaren gesetzlichen Regeln verarbeitet werden."},{"number":28,"title":"Digitale Selbstbestimmung","text":"Menschen haben Anspruch auf verständliche Informationen darüber, welche digitalen Systeme ihre Daten verarbeiten und zu welchem Zweck."},{"number":29,"title":"Analoge Teilhabe","text":"Wesentliche staatliche Leistungen müssen eine zumutbare nicht-digitale Alternative vorsehen."},{"number":30,"title":"Zugang zum Recht","text":"Jeder Mensch hat Anspruch auf wirksamen Rechtsschutz und ein faires Verfahren."},{"number":31,"title":"Unschuldsvermutung","text":"Bis zu einer rechtskräftigen Verurteilung gilt jede beschuldigte Person als unschuldig."},{"number":32,"title":"Verhältnismäßigkeit","text":"Staatliche Eingriffe müssen geeignet, erforderlich und angemessen sein."},{"number":33,"title":"Rückwirkungsverbot","text":"Strafbarkeit darf grundsätzlich nicht rückwirkend begründet oder verschärft werden."},{"number":34,"title":"Keine politische Justiz","text":"Gerichte und Strafverfolgung dürfen nicht zur Verfolgung politischer Gegner eingesetzt werden."},{"number":35,"title":"Recht auf Verteidigung","text":"Jede beschuldigte Person hat Anspruch auf wirksame Verteidigung und auf Kenntnis der gegen sie erhobenen Vorwürfe."},{"number":36,"title":"Opferschutz","text":"Opfer von Straftaten haben Anspruch auf Schutz, Information und Zugang zu geeigneter Unterstützung."},{"number":37,"title":"Jugendschutz im Strafrecht","text":"Jugendliche werden nach einem eigenständigen, entwicklungsorientierten Rechtssystem behandelt."},{"number":38,"title":"Resozialisierung","text":"Strafvollzug soll Sicherheit gewährleisten und zugleich die Rückkehr in ein rechtmäßiges Leben ermöglichen."},{"number":39,"title":"Recht auf grundlegende Versorgung","text":"Niemand darf ohne Zugang zu lebensnotwendiger Versorgung gelassen werden."},{"number":40,"title":"Schutz vor Obdachlosigkeit","text":"Öffentliche Stellen müssen angemessene Verfahren zur Vermeidung und Beendigung von Wohnungslosigkeit vorhalten."},{"number":41,"title":"Schutz vor Ausbeutung","text":"Arbeit und wirtschaftliche Abhängigkeit dürfen nicht zur rechtswidrigen Ausbeutung von Menschen führen."},{"number":42,"title":"Kinderrechte","text":"Kinder und Jugendliche besitzen eigene Rechte und erhalten besonderen Schutz."},{"number":43,"title":"Rechte älterer Menschen","text":"Ältere Menschen behalten volle gesellschaftliche Teilhabe und Entscheidungsfreiheit."},{"number":44,"title":"Rechte von Menschen mit Behinderungen","text":"Barrierefreiheit und gleichberechtigte Teilhabe werden schrittweise als verbindliche öffentliche Aufgabe umgesetzt."},{"number":45,"title":"Staatliche Neutralität","text":"Der Staat darf keine persönliche Weltanschauung oder Lebensform als verbindlich vorschreiben."},{"number":46,"title":"Verfassungsfestigkeit","text":"Die Grundrechte bilden den verbindlichen Rahmen jeder weiteren Regelung."},{"number":47,"title":"Schutz des Rechtswegs","text":"Die Regelungen zu schutz des rechtswegs werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."}]},"II":{"title":"Familie, Kinder, Bildung und Forschung","articles":[{"number":48,"title":"Familie","text":"Familien und andere verantwortliche Sorgegemeinschaften stehen unter besonderem Schutz."},{"number":49,"title":"Elterliche Verantwortung","text":"Eltern tragen die vorrangige Verantwortung für die Erziehung ihrer Kinder innerhalb der Grenzen der Kinderrechte."},{"number":50,"title":"Staatliche Zurückhaltung","text":"Der Staat greift in gewöhnliche Erziehungsentscheidungen nur ein, wenn konkrete Gefahren oder erhebliche Rechtsverletzungen vorliegen."},{"number":51,"title":"Kindeswohl","text":"Bei staatlichen Entscheidungen, die Kinder betreffen, ist ihr Wohl vorrangig zu berücksichtigen."},{"number":52,"title":"Frühe Unterstützung","text":"Familien erhalten frühzeitig freiwillige Unterstützungsangebote, wenn Belastungen die Entwicklung eines Kindes gefährden können."},{"number":53,"title":"Entlastung","text":"Eltern dürfen Hilfen zur Betreuung, Pflege und Alltagsentlastung in Anspruch nehmen, ohne dadurch ihre familiäre Verantwortung zu verlieren."},{"number":54,"title":"Familiengerechte Grundversorgung","text":"Haushalte mit Kindern erhalten zusätzliche Grundversorgungs- und Wohnressourcen nach transparenten Regeln."},{"number":55,"title":"Gesundheit von Kindern","text":"Kinder und Jugendliche erhalten besonderen Zugang zu medizinischer Versorgung, Prävention und psychologischer Unterstützung."},{"number":56,"title":"Schutz vor Gewalt","text":"Körperliche, psychische und sexualisierte Gewalt gegen Kinder wird konsequent verfolgt und präventiv bekämpft."},{"number":57,"title":"Frühe Bildung","text":"Jedes Kind erhält Zugang zu hochwertiger frühkindlicher Bildung und Betreuung."},{"number":58,"title":"Schulbildung","text":"Schulische Bildung vermittelt Grundlagenwissen, selbstständiges Denken, soziale Fähigkeiten und Orientierung."},{"number":59,"title":"Lernfreiheit","text":"Innerhalb verbindlicher Grundlagen sollen Lernwege an Interessen, Fähigkeiten und Entwicklungsstand angepasst werden."},{"number":60,"title":"Weniger Prüfungsdruck","text":"Leistungsfeststellungen werden auf für Bildung und Orientierung relevante Grundlagen konzentriert."},{"number":61,"title":"Projektlernen","text":"Schulen ermöglichen individuelle und gemeinsame Projekte, in denen Interessen praktisch erprobt werden."},{"number":62,"title":"Gesellschafts- und Eigenentwicklungskunde","text":"Ein verbindlicher Lernbereich unterstützt junge Menschen dabei, eigene Interessen, Fähigkeiten und mögliche Beiträge zur Gesellschaft zu erkennen."},{"number":63,"title":"Berufsorientierung","text":"Berufsorientierung informiert über Tätigkeiten, Ausbildungswege, Anforderungen, Einkommen und gesellschaftlichen Bedarf."},{"number":64,"title":"Neuorientierung","text":"Ein einmal eingeschlagener Bildungs- oder Berufsweg darf ohne unnötige Hürden geändert werden."},{"number":65,"title":"Gleichwertige Bildungswege","text":"Praktische, akademische, technische, kreative und soziale Bildungswege werden als gleichwertige Formen gesellschaftlicher Entwicklung anerkannt."},{"number":66,"title":"Ausbildung","text":"Ausbildungsplätze sollen praktische Fähigkeiten, fachliche Grundlagen und verantwortliches Handeln verbinden."},{"number":67,"title":"Hochschulen","text":"Hochschulen erhalten fachliche und organisatorische Freiheit innerhalb der gesetzlichen Grundordnung."},{"number":68,"title":"Akademische Freiheit","text":"Forschung und Lehre dürfen nicht wegen unliebsamer Ergebnisse politisch unterdrückt werden."},{"number":69,"title":"Forschungsförderung","text":"Öffentliche Forschungsförderung orientiert sich an nachvollziehbaren wissenschaftlichen und gesellschaftlichen Kriterien."},{"number":70,"title":"Medizinische Forschung","text":"Forschung zur Verbesserung von Gesundheit und Versorgung kann besonders gefördert werden, wenn ein plausibler gesellschaftlicher Nutzen besteht."},{"number":71,"title":"Grundlagenforschung","text":"Auch Forschung ohne unmittelbaren wirtschaftlichen Nutzen kann aus öffentlichen Mitteln unterstützt werden."},{"number":72,"title":"Bürgerentscheid über Forschung","text":"Bei außergewöhnlich großen oder langfristigen Forschungsprogrammen kann eine demokratische Entscheidung über den öffentlichen Finanzierungsrahmen vorgesehen werden."},{"number":73,"title":"Wissenschaftliche Integrität","text":"Forschungseinrichtungen müssen Interessenkonflikte, Finanzierungsquellen und wesentliche methodische Einschränkungen offenlegen."},{"number":74,"title":"Offene Kritik","text":"Wissenschaftliche Aussagen dürfen öffentlich kritisiert und durch Gegenbefunde geprüft werden."},{"number":75,"title":"Lehrerberuf","text":"Lehrkräfte erhalten angemessene Vergütung, Weiterbildung und fachliche Autonomie."},{"number":76,"title":"Berufsprämie Bildung","text":"Für Lehrtätigkeit kann eine gesellschaftlich festgelegte Bedarfskomponente vorgesehen werden; der Entwurf sieht zunächst zehn Prozent vor."},{"number":77,"title":"Kinderbetreuung","text":"Betreuungsangebote sollen wohnortnah, verlässlich und mit unterschiedlichen Arbeits- und Familienmodellen vereinbar sein."},{"number":78,"title":"Jugendbeteiligung","text":"Kinder und Jugendliche erhalten altersgerechte Möglichkeiten, Entscheidungen über sie betreffende Angelegenheiten mitzugestalten."},{"number":79,"title":"Schutz vor Überforderung","text":"Bildungsinstitutionen achten auf angemessene Belastung und erkennen psychische Überforderung frühzeitig."},{"number":80,"title":"Digitale Bildung","text":"Digitale Kompetenzen werden vermittelt, ohne analoge Fähigkeiten und kritisches Denken zu ersetzen."},{"number":81,"title":"Medienkompetenz","text":"Schülerinnen und Schüler lernen Quellen zu prüfen, Unsicherheit zu erkennen und unterschiedliche Perspektiven zu vergleichen."},{"number":82,"title":"Freiwillige Vertiefung","text":"Über verbindliche Grundlagen hinaus können Schulen und Lernende zusätzliche Schwerpunkte wählen."},{"number":83,"title":"Lebenslanges Lernen","text":"Weiterbildung und Umschulung bleiben auch im Erwachsenenalter zugänglich."},{"number":84,"title":"Bildungsgerechtigkeit","text":"Finanzielle oder soziale Herkunft darf den Zugang zu grundlegender Bildung nicht bestimmen."},{"number":85,"title":"Lernmittel","text":"Notwendige Lernmittel werden so bereitgestellt, dass wirtschaftliche Unterschiede nicht zum Ausschluss führen."},{"number":86,"title":"Forschungsschutz","text":"Wissenschaftler dürfen Ergebnisse veröffentlichen, solange gesetzliche Schutzgüter gewahrt bleiben."},{"number":87,"title":"Technologiefolgen","text":"Bei neuen Technologien werden Nutzen, Risiken, Abhängigkeiten und Alternativen systematisch untersucht."},{"number":88,"title":"Forschungsdaten","text":"Forschungsdaten werden nach rechtlichen und wissenschaftlichen Standards sicher verarbeitet."},{"number":89,"title":"Internationale Wissenschaft","text":"Internationale Forschung wird ermöglicht, solange Menschenrechte, Sicherheit und wissenschaftliche Unabhängigkeit gewahrt bleiben."},{"number":90,"title":"Schutz geistiger Arbeit","text":"Urheberrechte und andere Schutzrechte werden so ausgestaltet, dass Innovation und Zugang zu Wissen miteinander vereinbar bleiben."},{"number":91,"title":"Lehrplanprüfung","text":"Lehrpläne werden regelmäßig auf Aktualität, Belastung und gesellschaftliche Relevanz überprüft."},{"number":92,"title":"Bildungsbericht","text":"Eine unabhängige Stelle veröffentlicht regelmäßig nachvollziehbare Daten über Bildungsergebnisse und Zugangschancen."},{"number":93,"title":"Keine Bildungsmonopole","text":"Staatliche Bildung darf alternative zulässige Bildungsformen nicht ohne sachlichen Grund verdrängen."},{"number":94,"title":"Schulgesundheit","text":"Die Regelungen zu schulgesundheit werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."}]},"III":{"title":"Wirtschaft und Unternehmen","articles":[{"number":95,"title":"Wirtschaftliche Vielfalt","text":"Die Wirtschaftsordnung ermöglicht private, gemeinschaftliche, genossenschaftliche und andere rechtmäßige Unternehmensformen."},{"number":96,"title":"Wettbewerb","text":"Offener Wettbewerb wird geschützt, soweit er nicht durch berechtigte soziale, ökologische oder sicherheitsbezogene Regeln begrenzt werden muss."},{"number":97,"title":"Wettbewerbsaufsicht","text":"Eine unabhängige Wettbewerbsbehörde überwacht Marktmacht, Kartelle und missbräuchliche Abhängigkeiten."},{"number":98,"title":"Markteintritt","text":"Neue Unternehmen dürfen nicht durch unnötige regulatorische oder wirtschaftliche Barrieren vom Markt ferngehalten werden."},{"number":99,"title":"Preisbildung","text":"Preise entstehen grundsätzlich durch Angebot und Nachfrage sowie durch die realen Kosten der Leistung."},{"number":100,"title":"Preisbremsen","text":"Zeitlich begrenzte Preisbremsen können bei außergewöhnlichen Versorgungslagen eingesetzt werden."},{"number":101,"title":"Kostenuntergrenze","text":"Eine Preisregel darf nicht dauerhaft Preise unter den realen Produktionskosten erzwingen."},{"number":102,"title":"Transparenz von Preismaßnahmen","text":"Außergewöhnliche Preismaßnahmen müssen begründet, befristet und überprüfbar sein."},{"number":103,"title":"Unternehmensgründung","text":"Die Gründung eines Unternehmens steht grundsätzlich allen offen, die die gesetzlichen Voraussetzungen erfüllen."},{"number":104,"title":"Gründeranteil","text":"Der Gründer erhält grundsätzlich fünfzig Prozent des vorgesehenen Unternehmensanteils, sofern die Gründungsvereinbarung nichts sachlich anderes bestimmt."},{"number":105,"title":"Mitarbeiteranteil","text":"Die Beschäftigten halten gemeinsam grundsätzlich die übrigen fünfzig Prozent des vorgesehenen Unternehmensanteils."},{"number":106,"title":"Abweichende Beteiligung","text":"Abweichungen können bei nachvollziehbaren Finanzierungs-, Risiko- oder Sanierungsbedingungen vereinbart werden."},{"number":107,"title":"Stimmrechte","text":"Eigentums- und Stimmrechte werden getrennt geregelt, soweit dies für Unternehmensführung und Beteiligung erforderlich ist."},{"number":108,"title":"Mitarbeitervertretung","text":"Beschäftigte erhalten wirksame Rechte bei wesentlichen Entscheidungen über Arbeit, Sicherheit und langfristige Unternehmensentwicklung."},{"number":109,"title":"Gewerkschaften","text":"Gewerkschaften können Interessen der Beschäftigten unabhängig vertreten."},{"number":110,"title":"Unternehmensleitung","text":"Die Unternehmensleitung trägt Verantwortung für Rechtmäßigkeit, wirtschaftliche Tragfähigkeit und sichere Arbeitsbedingungen."},{"number":111,"title":"Zusammenarbeit","text":"Unternehmensleitung und Arbeitnehmervertretungen sollen Konflikte zunächst durch verhandelte Lösungen bearbeiten."},{"number":112,"title":"Gewinnbeteiligung","text":"Beschäftigte sollen angemessen am Erfolg eines Unternehmens beteiligt werden, wenn dies mit seiner Stabilität vereinbar ist."},{"number":113,"title":"Verlustverantwortung","text":"Beteiligungsrechte dürfen nicht so ausgestaltet werden, dass Beschäftigte für Verluste ohne angemessene Schutzmechanismen persönlich haften."},{"number":114,"title":"Gründer-Nachfolge","text":"Ein persönlicher Gründeranteil kann bei Tod oder dauerhaftem Ausscheiden in die gemeinschaftliche Unternehmensstruktur übergehen."},{"number":115,"title":"Nachfolgeperson","text":"Ein Gründer darf eine Person bestimmen, die innerhalb klarer Grenzen ein erweitertes Stimmrecht erhält, um langfristige Unternehmensgrundsätze fortzuführen."},{"number":116,"title":"Grenzen des Sonderstimmrechts","text":"Ein Sonderstimmrecht darf weder Grundrechte noch Arbeitnehmerrechte, Wettbewerbsrecht oder gesetzliche Aufsicht außer Kraft setzen."},{"number":117,"title":"Ende des Sonderstimmrechts","text":"Das Sonderstimmrecht endet bei den gesetzlich festgelegten Voraussetzungen, insbesondere bei Missbrauch oder dauerhaftem Wegfall seines Zwecks."},{"number":118,"title":"Keine Unternehmensaristokratie","text":"Unternehmensmacht darf nicht erblich auf unbegrenzte Zeit konzentriert werden."},{"number":119,"title":"Marktmachtprüfung","text":"Bei erheblicher Konzentration prüft die Wettbewerbsaufsicht, ob Alternativen bestehen und ob Gegenmaßnahmen erforderlich sind."},{"number":120,"title":"Neue Wettbewerber","text":"Wenn ein Markt dauerhaft ohne ausreichende Alternative bleibt, können öffentliche Mittel den Aufbau junger innovativer Wettbewerber unterstützen."},{"number":121,"title":"Staat als Marktteilnehmer","text":"Der Staat tritt nur dort selbst wirtschaftlich auf, wo ein nachvollziehbarer öffentlicher Zweck besteht."},{"number":122,"title":"Subventionsprüfung","text":"Öffentliche Unternehmenshilfen müssen Zweck, Dauer, Kosten und Rückfallrisiken offenlegen."},{"number":123,"title":"Keine Rettung ohne Prüfung","text":"Nicht tragfähige Unternehmen erhalten keine automatische dauerhafte Rettung aus öffentlichen Mitteln."},{"number":124,"title":"Insolvenz","text":"Insolvenzverfahren sollen Gläubiger, Beschäftigte, Eigentum und die Fortführung gesellschaftlich wichtiger Funktionen angemessen berücksichtigen."},{"number":125,"title":"Arbeitsplatzsicherung","text":"Bei systemrelevanten Betrieben können Übergangsmaßnahmen zur Sicherung kritischer Leistungen vorgesehen werden."},{"number":126,"title":"Arbeitszeit","text":"Arbeitszeiten müssen Gesundheit, Sicherheit und Vereinbarkeit mit dem Privatleben berücksichtigen."},{"number":127,"title":"Arbeitsschutz","text":"Arbeitgeber sind verpflichtet, sichere und gesundheitlich vertretbare Arbeitsbedingungen zu gewährleisten."},{"number":128,"title":"Mindeststandards","text":"Arbeitsverträge müssen gesetzliche Mindeststandards zu Vergütung, Sicherheit und Mitwirkung einhalten."},{"number":129,"title":"Vergütung","text":"Vergütung darf nach Verantwortung, Qualifikation, Belastung, Leistung und gesellschaftlichem Bedarf differieren."},{"number":130,"title":"Gleichwertige Arbeit","text":"Unterschiedliche Berufe können unterschiedliche Vergütung haben, ohne dass dadurch der menschliche Wert ihrer Ausübenden bewertet wird."},{"number":131,"title":"Berufsprämien","text":"Für gesellschaftlich besonders benötigte Berufe können zeitlich überprüfbare Zuschläge vorgesehen werden."},{"number":132,"title":"Medizinische Berufe","text":"Der Entwurf sieht zunächst einen Zuschlag von zwanzig Prozent für Ärztinnen und Ärzte vor."},{"number":133,"title":"Pflegeberufe","text":"Der Entwurf sieht zunächst einen Zuschlag von fünfzehn Prozent für Pflegeberufe vor."},{"number":134,"title":"Polizeiberufe","text":"Der Entwurf sieht zunächst einen Zuschlag von fünf Prozent für Polizeiberufe vor."},{"number":135,"title":"Feuerwehr","text":"Der Entwurf sieht zunächst einen Zuschlag von fünf Prozent für Feuerwehrberufe vor."},{"number":136,"title":"Bedarfsprüfung","text":"Berufszuschläge werden regelmäßig anhand gesellschaftlicher Nachfrage und Arbeitsbedingungen überprüft."},{"number":137,"title":"Unternehmensdaten","text":"Unternehmen müssen für Aufsicht und gesetzliche Planung notwendige Daten nachvollziehbar bereitstellen."},{"number":138,"title":"Geschäftsgeheimnisse","text":"Legitime Geschäftsgeheimnisse werden geschützt, soweit dadurch keine Rechtsverletzungen oder erhebliche öffentliche Risiken verdeckt werden."},{"number":139,"title":"Wettbewerbsinformationen","text":"Wettbewerbsbehörden dürfen notwendige Unternehmensdaten unter strengen Datenschutz- und Verfahrensregeln auswerten."},{"number":140,"title":"Internationale Unternehmen","text":"Ausländische Unternehmen können tätig sein, sofern sie die gleichen grundlegenden Regeln einhalten."}]},"IV":{"title":"Familie, Religion, Grundversorgung und Gesellschaft","articles":[{"number":141,"title":"Ehe und Partnerschaft","text":"Ehe und andere freiwillige Partnerschaften werden rechtlich geschützt, ohne eine bestimmte Lebensform vorzuschreiben."},{"number":142,"title":"Familienfreundlichkeit","text":"Gesellschaftliche Rahmenbedingungen sollen Familiengründung und verantwortliche Partnerschaft erleichtern."},{"number":143,"title":"Haushaltsressourcen","text":"Grundressourcen eines Haushalts werden nach Haushaltsgröße und besonderen Bedürfnissen bemessen."},{"number":144,"title":"Kinder in Haushaltsberechnung","text":"Kinder werden bei der Berechnung grundlegender Haushaltsressourcen grundsätzlich wie vollwertige Haushaltsmitglieder berücksichtigt."},{"number":145,"title":"Wohnraumbudget","text":"Wohnraumansprüche berücksichtigen Haushaltsgröße, Kinder und besondere Bedürfnisse."},{"number":146,"title":"Fahrzeugbudget","text":"Ein Haushalt kann innerhalb der Grundversorgung ein Fahrzeugbudget erhalten, das sich bei zusätzlichen Kindern erhöht."},{"number":147,"title":"Mobilität","text":"Öffentliche Mobilität soll so ausgebaut werden, dass ein eigenes Fahrzeug nicht Voraussetzung gesellschaftlicher Teilhabe ist."},{"number":148,"title":"Öffentlicher Verkehr","text":"Grundlegende öffentliche Verkehrsleistungen werden grundsätzlich kostenfrei oder über die allgemeine Finanzierung bereitgestellt."},{"number":149,"title":"Religion und Staat","text":"Religiöse Gemeinschaften dürfen frei wirken, bleiben aber an allgemeines Recht und die Grundrechte gebunden."},{"number":150,"title":"Religiöse Neutralität","text":"Keine Religion erhält staatliche Vorrangstellung."},{"number":151,"title":"Gewissensfreiheit","text":"Religiöse oder nichtreligiöse Gewissensentscheidungen werden geschützt, soweit Rechte anderer gewahrt bleiben."},{"number":152,"title":"Religiöse Bildung","text":"Religiöse Bildung darf angeboten werden, sofern sie freiwillig und weltanschaulich transparent erfolgt."},{"number":153,"title":"Religionsgemeinschaften","text":"Religionsgemeinschaften organisieren ihre inneren Angelegenheiten grundsätzlich selbst."},{"number":154,"title":"Missbrauchsschutz","text":"Religiöse oder weltanschauliche Zugehörigkeit rechtfertigt keinen Schutz vor allgemeinem Straf- oder Zivilrecht."},{"number":155,"title":"Grundversorgung","text":"Lebensnotwendige Grundversorgung wird als gemeinsame gesellschaftliche Aufgabe organisiert."},{"number":156,"title":"Grundnahrung","text":"Jede Person erhält Zugang zu einer regional verfügbaren grundlegenden Lebensmittelversorgung."},{"number":157,"title":"Wasser","text":"Sauberes Trinkwasser gehört zur unverzichtbaren Grundversorgung."},{"number":158,"title":"Gesundheitsversorgung","text":"Notwendige medizinische Versorgung steht allen Menschen offen."},{"number":159,"title":"Pflege","text":"Pflegeleistungen werden nach Bedarf und nicht allein nach individueller Zahlungsfähigkeit zugänglich gemacht."},{"number":160,"title":"Soziale Sicherheit","text":"Das System schützt gegen Krankheit, Pflegebedürftigkeit, Arbeitslosigkeit, Erwerbsunfähigkeit, Alter, Unfall und besondere Notlagen."},{"number":161,"title":"Soziale Teilhabe","text":"Soziale Sicherung soll nicht nur Existenz sichern, sondern gesellschaftliche Teilhabe ermöglichen."},{"number":162,"title":"Ältere Menschen","text":"Ältere Menschen sollen aktiv am gesellschaftlichen Leben teilnehmen können."},{"number":163,"title":"Generationenprojekte","text":"Schulen, Betriebe und Gemeinden können generationenübergreifende Projekte fördern."},{"number":164,"title":"Erfahrungstransfer","text":"Erfahrung älterer Menschen kann freiwillig in Ausbildung, Beratung und Gemeinwesen eingebracht werden."},{"number":165,"title":"Pflegeentlastung","text":"Pflegende Angehörige erhalten Entlastungs- und Unterstützungsangebote."},{"number":166,"title":"Menschen mit Pflegebedarf","text":"Pflegebedürftige behalten Selbstbestimmung und werden in Entscheidungen über ihre Versorgung einbezogen."},{"number":167,"title":"Armut","text":"Öffentliche Maßnahmen sollen extreme materielle Not verhindern, ohne Menschen unnötig zu bevormunden."},{"number":168,"title":"Soziale Beratung","text":"Menschen in Notlagen erhalten Zugang zu unabhängiger Beratung."},{"number":169,"title":"Gemeinnützigkeit","text":"Gemeinnützige Organisationen können gesellschaftliche Aufgaben übernehmen, wenn ihre Finanzierung und Arbeitsweise transparent sind."},{"number":170,"title":"Kirchen und Gemeinnützige","text":"Kirchen und andere gemeinnützige Einrichtungen können bei gemeinwohlorientierten Arbeitsangeboten mitwirken."},{"number":171,"title":"Freiwilligkeit","text":"Gemeinwohlorientierte Tätigkeiten sollen grundsätzlich freiwillige Mitwirkung fördern; verpflichtende Maßnahmen bedürfen einer klaren gesetzlichen Grundlage und müssen verhältnismäßig sein."},{"number":172,"title":"Schutz vor Zwangsarbeit","text":"Niemand darf durch soziale Abhängigkeit zu entwürdigender oder unverhältnismäßiger Arbeit gezwungen werden."},{"number":173,"title":"Arbeitsvermittlung","text":"Arbeitslose erhalten Zugang zu Beratung, Qualifizierung und Vermittlung."},{"number":174,"title":"Passende Arbeit","text":"Vermittlung berücksichtigt Fähigkeiten, Gesundheit, Zumutbarkeit und langfristige Entwicklung."},{"number":175,"title":"Temporäre Unternehmensvermittlung","text":"Bei geeignetem Bedarf können Arbeitsuchende mit ihrer Zustimmung zeitweise in Unternehmen vermittelt werden, auch wenn dort eine höhere Vergütung angeboten wird."},{"number":176,"title":"Arbeitslosensicherung","text":"Bei fehlender Beschäftigung wird eine existenzsichernde soziale Leistung gewährleistet."},{"number":177,"title":"Gemeinwohlbeitrag","text":"Wer Leistungen bezieht, kann innerhalb gesetzlicher Grenzen an zumutbaren gemeinnützigen Angeboten teilnehmen."},{"number":178,"title":"Beschwerderecht","text":"Betroffene können Entscheidungen der Sozialverwaltung überprüfen lassen."},{"number":179,"title":"Sozialdaten","text":"Sozialdaten werden zweckgebunden und besonders geschützt verarbeitet."},{"number":180,"title":"Integration","text":"Menschen, die neu in die Gesellschaft kommen, erhalten Zugang zu Sprache, Bildung, Arbeit und gesellschaftlicher Teilhabe."},{"number":181,"title":"Gemeinschaft und Individualität","text":"Gemeinschaftliche Verantwortung darf individuelle Lebensentwürfe nicht unnötig vereinheitlichen."},{"number":182,"title":"Kulturelle Vielfalt","text":"Kulturelle Vielfalt wird geschützt, solange grundlegende Rechte und Gesetze gewahrt bleiben."},{"number":183,"title":"Sport und Bewegung","text":"Zugang zu Bewegung und Sport wird als Teil von Gesundheit und gesellschaftlicher Teilhabe unterstützt."},{"number":184,"title":"Kultur","text":"Kulturelle Einrichtungen und freie Kultur können öffentlich unterstützt werden, ohne dass der Staat Inhalte politisch vorgibt."},{"number":185,"title":"Öffentliche Räume","text":"Gemeinden sorgen für zugängliche und sichere öffentliche Räume."},{"number":186,"title":"Nachbarschaft","text":"Nachbarschaftliche Selbsthilfe kann durch geeignete Infrastruktur unterstützt werden."},{"number":187,"title":"Ehrenamt","text":"Freiwilliges gesellschaftliches Engagement wird anerkannt und darf nicht durch unnötige Bürokratie behindert werden."},{"number":188,"title":"Gemeinschaftliche Verantwortung","text":"Gesellschaftliche Solidarität ist eine gemeinsame Aufgabe von Staat, Unternehmen, Familien, Vereinen und Einzelpersonen."},{"number":189,"title":"Sozialbericht","text":"Eine unabhängige Stelle veröffentlicht regelmäßig Daten über soziale Teilhabe und Grundversorgung."},{"number":190,"title":"Soziale Zielprüfung","text":"Neue Maßnahmen werden darauf geprüft, ob sie Menschen tatsächlich helfen oder lediglich Verwaltungslasten erzeugen."},{"number":191,"title":"Familienberatung","text":"Die Regelungen zu familienberatung werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":192,"title":"Elternzeit","text":"Die Regelungen zu elternzeit werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":193,"title":"Pflege von Kindern","text":"Die Regelungen zu pflege von kindern werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":194,"title":"Kinderschutzbehörden","text":"Die Regelungen zu kinderschutzbehörden werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."}]},"V":{"title":"Gesundheit und medizinische Ordnung","articles":[{"number":195,"title":"Gesundheitsrecht","text":"Gesundheitsversorgung orientiert sich an medizinischem Bedarf, Menschenwürde und nachvollziehbaren Prioritäten."},{"number":196,"title":"Vorsorge","text":"Prävention und Gesundheitsbildung werden als Teil der Versorgung gefördert."},{"number":197,"title":"Notfallversorgung","text":"In medizinischen Notfällen erhält jede Person unverzüglich notwendige Hilfe."},{"number":198,"title":"Kinderpriorität","text":"Bei vergleichbaren Versorgungslagen erhalten Kinder und Jugendliche besonderen Schutz."},{"number":199,"title":"Pflegeversorgung","text":"Pflege wird als gleichwertiger Bestandteil des Gesundheitswesens behandelt."},{"number":200,"title":"Gesundheitsberufe","text":"Gesundheitsberufe benötigen qualifizierte Ausbildung und regelmäßige Fortbildung."},{"number":201,"title":"Medizinische Qualität","text":"Behandlungen sollen nach anerkannten wissenschaftlichen Standards erfolgen."},{"number":202,"title":"Patientenautonomie","text":"Patientinnen und Patienten werden in medizinische Entscheidungen einbezogen, soweit ihre Entscheidungsfähigkeit dies zulässt."},{"number":203,"title":"Einwilligung","text":"Medizinische Eingriffe bedürfen grundsätzlich einer informierten Einwilligung, außer in gesetzlich geregelten Notfällen."},{"number":204,"title":"Gesundheitsdaten","text":"Gesundheitsdaten gehören zu den besonders geschützten personenbezogenen Daten."},{"number":205,"title":"Forschung und Versorgung","text":"Forschung darf Versorgung verbessern, ohne Patientenrechte aufzugeben."},{"number":206,"title":"Arzneimittel","text":"Arzneimittelversorgung soll sicher, verfügbar und nach wissenschaftlichen Standards kontrolliert sein."},{"number":207,"title":"Medizinische Reserven","text":"Für kritische medizinische Güter werden angemessene strategische Vorräte aufgebaut."},{"number":208,"title":"Pandemievorsorge","text":"Für übertragbare Krankheiten werden Vorsorgepläne mit abgestuften und zeitlich begrenzten Maßnahmen vorgehalten."},{"number":209,"title":"Gesundheitskrisen","text":"Gesundheitskrisen werden fachlich bewertet; politische Entscheidungen bleiben demokratisch legitimiert."},{"number":210,"title":"Psychische Gesundheit","text":"Psychische Gesundheit wird gleichberechtigt mit körperlicher Gesundheit behandelt."},{"number":211,"title":"Rehabilitation","text":"Nach Krankheit oder Unfall wird die Rückkehr zu selbstbestimmter Teilhabe unterstützt."},{"number":212,"title":"Berufliche Gesundheit","text":"Arbeitsbedingungen sollen gesundheitliche Schäden verhindern."},{"number":213,"title":"Gesundheitskontrolle","text":"Unabhängige Stellen überwachen Qualität, Patientenschutz und Interessenkonflikte."},{"number":214,"title":"Gesundheitsbericht","text":"Das Gesundheitswesen wird regelmäßig anhand von Versorgung, Qualität, Kosten und Zugang überprüft."}]},"VI":{"title":"Landwirtschaft, Ernährung, Wohnen, Energie und Infrastruktur","articles":[{"number":215,"title":"Landwirtschaftliche Grundlage","text":"Landwirtschaft dient Ernährung, Landschaftspflege, ökologischer Stabilität und wirtschaftlicher Tätigkeit."},{"number":216,"title":"Ökologischer Standard","text":"Inländische Grundproduktion soll nach einem verbindlichen ökologischen Standard erfolgen; der Entwurf orientiert sich am Demeter-Niveau oder einem gleichwertigen Standard."},{"number":217,"title":"Bodenfruchtbarkeit","text":"Böden sollen langfristig fruchtbar und ökologisch belastbar erhalten werden."},{"number":218,"title":"Wasserschutz","text":"Landwirtschaft und Industrie müssen die langfristige Qualität von Wasserressourcen berücksichtigen."},{"number":219,"title":"Ernteausfälle","text":"Ernteausfälle werden durch Vorräte, regionale Umverteilung, zusätzliche Produktionskapazität und erforderlichenfalls Handel abgefedert."},{"number":220,"title":"Gewächshausproduktion","text":"Kontrollierte Gewächshausproduktion kann zur Krisenvorsorge und Versorgungssicherung eingesetzt werden."},{"number":221,"title":"Unterirdischer Anbau","text":"Geeignete unterirdische Anlagen, Stollen oder andere sichere Räume können für kontrollierte Produktion genutzt werden."},{"number":222,"title":"Produktionssicherheit","text":"Zusätzliche Produktionskapazitäten sollen so verteilt werden, dass einzelne Ausfälle nicht das gesamte System gefährden."},{"number":223,"title":"Saatgut","text":"Strategisch wichtige Saatgutbestände werden geschützt und erhalten."},{"number":224,"title":"Landwirtschaftliche Forschung","text":"Forschung zu resilienten und ökologischen Anbaumethoden wird unterstützt."},{"number":225,"title":"Regionalität","text":"Regionale Lebensmittel sollen die Grundversorgung möglichst weitgehend tragen."},{"number":226,"title":"Importe","text":"Exotische und ergänzende Lebensmittelimporte bleiben zulässig, dürfen aber die regionale Grundversorgung nicht systematisch verdrängen."},{"number":227,"title":"Exporte","text":"Überschüsse können international gehandelt werden, soweit die inländische Versorgung gesichert bleibt."},{"number":228,"title":"Lebensmittelreserven","text":"Für wichtige Lebensmittel werden angemessene Vorräte nach Risiko und Haltbarkeit bestimmt."},{"number":229,"title":"Lebensmittelqualität","text":"Grundnahrungsmittel unterliegen nachvollziehbaren Qualitäts- und Sicherheitsstandards."},{"number":230,"title":"Lebensmittelpreise","text":"Preisregeln dürfen Versorgung und Produktion nicht dauerhaft durch Preise unter realen Kosten gefährden."},{"number":231,"title":"Wasserinfrastruktur","text":"Trinkwasser- und Abwassersysteme werden als kritische Infrastruktur behandelt."},{"number":232,"title":"Wohnraumanspruch","text":"Jeder Haushalt hat Anspruch auf angemessenen Wohnraum nach Haushaltsgröße und Bedarf."},{"number":233,"title":"Wohnraumverteilung","text":"Wohnraum wird nach transparenten Regeln vergeben, die Größe, Bedarf, Kinder und Verfügbarkeit berücksichtigen."},{"number":234,"title":"Umzug","text":"Bei Veränderung der Lebenssituation soll ein geeigneter Wohnungstausch oder eine neue Zuweisung ermöglicht werden, ohne unnötige Verdrängung."},{"number":235,"title":"Wohnungsbau","text":"Neue Wohnungen werden entsprechend regionalem Bedarf geplant."},{"number":236,"title":"Bestandsschutz","text":"Bewohnbarer Wohnraum soll nicht ohne sachlichen Grund dauerhaft leer stehen."},{"number":237,"title":"Barrierefreiheit","text":"Wohnraum soll bei Neubau und Sanierung zunehmend barrierearm oder barrierefrei gestaltet werden."},{"number":238,"title":"Energieversorgung","text":"Energieversorgung muss sicher, bezahlbar, resilient und langfristig ökologisch tragfähig sein."},{"number":239,"title":"Energievielfalt","text":"Die Energieversorgung soll nicht von einer einzigen Technologie oder Lieferquelle abhängen."},{"number":240,"title":"Wasserkraft","text":"Wasserkraft kann Teil der Energieversorgung sein, soweit ökologische Anforderungen eingehalten werden."},{"number":241,"title":"Solarenergie","text":"Solarenergie wird als dezentrale Energiequelle ausgebaut."},{"number":242,"title":"Kernenergie","text":"Kleine modulare Reaktoren können als Übergangstechnologie geprüft und eingesetzt werden, bis gleichwertige oder bessere Alternativen verfügbar sind."},{"number":243,"title":"Netzstabilität","text":"Stromnetze werden dezentral, redundant und gegen Ausfälle geschützt."},{"number":244,"title":"Energiespeicher","text":"Speicher werden zur Abfederung von Schwankungen und Krisen ausgebaut."},{"number":245,"title":"Wärmeversorgung","text":"Wärmeversorgung soll unterschiedliche Quellen und regionale Gegebenheiten berücksichtigen."},{"number":246,"title":"Verkehr","text":"Verkehrsinfrastruktur wird nach Versorgungssicherheit, Zugänglichkeit und Umweltverträglichkeit entwickelt."},{"number":247,"title":"Öffentlicher Verkehr","text":"Öffentlicher Verkehr wird als Teil der Grundmobilität finanziert."},{"number":248,"title":"Straßen","text":"Straßen werden nach notwendigem Verkehrs- und Versorgungsbedarf instand gehalten."},{"number":249,"title":"Schienen","text":"Schieneninfrastruktur soll regionale und überregionale Versorgung resilient verbinden."},{"number":250,"title":"Logistik","text":"Kritische Logistiksysteme müssen Ausweichwege und Notbetriebsverfahren vorhalten."},{"number":251,"title":"Lagerung","text":"Wichtige Güter erhalten angemessene dezentrale Lagerkapazitäten."},{"number":252,"title":"Reparatur","text":"Öffentliche Infrastruktur wird nach Lebenszykluskosten und Reparierbarkeit geplant."},{"number":253,"title":"Digitale Infrastruktur","text":"Digitale Netze werden als kritische Infrastruktur geschützt und redundant aufgebaut."},{"number":254,"title":"Analoge Reserve","text":"Für zentrale Verwaltungs-, Zahlungs- und Kommunikationsfunktionen bestehen analoge oder dezentrale Notfallverfahren."},{"number":255,"title":"Kommunikation","text":"Notfallkommunikation darf nicht von einem einzigen Anbieter abhängen."},{"number":256,"title":"Gebäude","text":"Öffentliche Gebäude sollen energieeffizient und krisenfest gestaltet werden."},{"number":257,"title":"Katastrophenschutz","text":"Katastrophenschutz hält Material, Personal und Kommunikationswege für größere Schadenslagen bereit."},{"number":258,"title":"Kommunale Infrastruktur","text":"Kommunen erhalten die notwendigen Mittel und Kompetenzen für lokale Versorgungssicherheit."},{"number":259,"title":"Regionale Selbstversorgung","text":"Regionen sollen grundlegende Versorgung teilweise selbst aufrechterhalten können."},{"number":260,"title":"Kritische Infrastruktur","text":"Kritische Infrastrukturen werden nach Abhängigkeiten und möglichen Kaskadeneffekten bewertet."},{"number":261,"title":"Versorgungskaskaden","text":"Bei Planung und Krisenvorsorge werden Wechselwirkungen zwischen Energie, Wasser, Nahrung, Verkehr, Kommunikation und Gesundheit berücksichtigt."},{"number":262,"title":"Infrastrukturprüfung","text":"Große Infrastrukturvorhaben werden vor Umsetzung auf Kosten, Nutzen, Risiken und Alternativen geprüft."},{"number":263,"title":"Infrastrukturreserve","text":"Für besonders kritische Anlagen werden Ersatzteile und Wiederherstellungskapazitäten vorgehalten."},{"number":264,"title":"Naturgefahren","text":"Infrastrukturplanung berücksichtigt Hochwasser, Dürre, Hitze, Stürme und andere Naturgefahren."},{"number":265,"title":"Wald","text":"Wälder werden als ökologische, wirtschaftliche und klimatische Ressourcen geschützt."},{"number":266,"title":"Biodiversität","text":"Biologische Vielfalt wird bei Landnutzung und Infrastrukturplanung berücksichtigt."},{"number":267,"title":"Tierwohl","text":"Tierhaltung muss unnötiges Leiden vermeiden und an überprüfbaren Haltungsstandards ausgerichtet sein."},{"number":268,"title":"Ressourcenschutz","text":"Endliche Rohstoffe werden sparsam und langfristig planbar genutzt."},{"number":269,"title":"Kreislaufwirtschaft","text":"Wiederverwendung, Reparatur und Recycling werden gegenüber unnötigem Verbrauch bevorzugt."},{"number":270,"title":"Altlasten","text":"Gefährliche Altlasten werden systematisch erfasst und saniert."},{"number":271,"title":"Infrastrukturtransparenz","text":"Wesentliche Infrastrukturentscheidungen werden öffentlich nachvollziehbar dokumentiert."},{"number":272,"title":"Bodenordnung","text":"Die Regelungen zu bodenordnung werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":273,"title":"Landvergabe","text":"Die Regelungen zu landvergabe werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":274,"title":"Landwirtschaftliche Ausbildung","text":"Die Regelungen zu landwirtschaftliche ausbildung werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."},{"number":275,"title":"Tiergesundheit","text":"Die Regelungen zu tiergesundheit werden durch transparente, überprüfbare und verhältnismäßige Verfahren umgesetzt. Zuständigkeiten, Finanzierung und Rechtsschutz müssen gesetzlich nachvollziehbar bestimmt werden."}]},"VII":{"title":"Geld, Steuern, Bürgerkapital und Finanzen","articles":[{"number":276,"title":"Zweck der Abgaben","text":"Öffentliche Abgaben finanzieren die tatsächlich notwendigen gemeinsamen Aufgaben."},{"number":277,"title":"Bedarfsorientierung","text":"Der Abgabenbedarf wird regelmäßig aus Ausgaben, Sozialleistungen, Infrastruktur, Bildung, Gesundheit, Forschung, Krisenvorsorge, Rücklagen und sonstigen Einnahmen berechnet."},{"number":278,"title":"Monatliche Berechnung","text":"Der Finanzbedarf wird mindestens monatlich neu berechnet."},{"number":279,"title":"Stufenweise Anpassung","text":"Änderungen der laufenden Abgaben erfolgen grundsätzlich schrittweise, damit Haushalte und Unternehmen Planungssicherheit behalten."},{"number":280,"title":"Änderungsgrenze","text":"Im Normalfall soll eine monatliche Veränderung der laufenden Abgabenquote höchstens einen halben Prozentpunkt betragen; außergewöhnliche Krisen müssen gesondert begründet werden."},{"number":281,"title":"Transparenter Finanzplan","text":"Die Berechnung der notwendigen Einnahmen wird öffentlich nachvollziehbar dargestellt."},{"number":282,"title":"Nichtsteuerliche Einnahmen","text":"Gebühren, Gewinne öffentlicher Unternehmen, Abgaben und sonstige Einnahmen werden vor einer zusätzlichen Belastung berücksichtigt."},{"number":283,"title":"Keine Zwecküberschüsse","text":"Überschüsse dürfen nicht ohne festgelegten Zweck dauerhaft als laufende Mehreinnahmen eingesetzt werden."},{"number":284,"title":"Krisenreserve","text":"In wirtschaftlich guten Jahren wird eine Reserve aufgebaut, die nicht für gewöhnliche laufende Ausgaben verwendet werden soll."},{"number":285,"title":"Reservehöhe","text":"Die Mindesthöhe der Reserve wird nach Risiko, Bevölkerungsgröße, kritischer Infrastruktur und Wiederherstellungszeit bestimmt."},{"number":286,"title":"Reserveverwendung","text":"Reservemittel dürfen bei außergewöhnlichen Krisen, schweren Versorgungslücken und vergleichbaren Notlagen eingesetzt werden."},{"number":287,"title":"Reserveaufbau","text":"Nach einer Krisennutzung wird ein Wiederaufbauplan beschlossen und veröffentlicht."},{"number":288,"title":"Vierfache Reserve","text":"Gesellschaftliche Stabilität wird nicht nur finanziell, sondern auch durch materielle Vorräte, Produktionskapazität und menschlich-soziale Handlungsfähigkeit abgesichert."},{"number":289,"title":"Reale Bilanz","text":"Neben Geldgrößen werden reale Ressourcen wie Nahrung, Wasser, Energie, Wohnraum, Rohstoffe, Maschinen, Transportmittel und medizinische Güter erfasst."},{"number":290,"title":"Ressourcenindex","text":"Ein öffentliches Lagebild kann reale Versorgungsindizes mit Warnstufen ausweisen."},{"number":291,"title":"Geldordnung","text":"Die Geldordnung dient der zuverlässigen Zahlungsfähigkeit, Preisstabilität und Finanzierung realer wirtschaftlicher Tätigkeit."},{"number":292,"title":"Zentralbank","text":"Die zentrale Geldinstitution führt die Währungs- und Liquiditätsordnung und ist von kurzfristiger politischer Weisung unabhängig."},{"number":293,"title":"Keine Geschäftsbanken","text":"Der Entwurf sieht keine klassischen kommerziellen Geschäftsbanken als notwendige Institution vor."},{"number":294,"title":"Persönliches Konto","text":"Jede Person erhält ein persönliches Zahlungskonto mit Schutz vor unbefugtem Zugriff."},{"number":295,"title":"Finanzielle Selbstverwaltung","text":"Menschen können ihre eigenen Zahlungen, Sparvorgänge und zulässigen Investitionen selbst verwalten."},{"number":296,"title":"Funktionstrennung","text":"Zahlungsverkehr, Investitionsentscheidungen, Unternehmensfinanzierung und öffentliche Finanzverwaltung werden organisatorisch getrennt."},{"number":297,"title":"Geldschöpfung","text":"Neue Geldmittel dürfen nicht automatisch allein zur Deckung staatlicher Ausgaben geschaffen werden."},{"number":298,"title":"Geldmengenprüfung","text":"Bei Entscheidungen über Geldschöpfung werden Preise, Produktion, Kreditvolumen, Investitionen, Beschäftigung, Geldumlauf, Kapazitäten und Ressourcenknappheit berücksichtigt."},{"number":299,"title":"Keine starre Wachstumsregel","text":"Die Geldordnung folgt keiner mechanischen Vorgabe, wonach Geldmenge immer im gleichen Verhältnis wachsen muss."},{"number":300,"title":"Kredit und Rückzahlung","text":"Kredit schafft zeitweise zusätzliche Kaufkraft und wird grundsätzlich mit Rückzahlung und realer wirtschaftlicher Leistung verbunden."},{"number":301,"title":"Krisenliquidität","text":"In Krisen kann zusätzliche Liquidität bereitgestellt werden, ohne wirtschaftlich nicht tragfähige Unternehmen automatisch dauerhaft zu retten."},{"number":302,"title":"Sofortkredit","text":"Jede Person kann nach transparenten Regeln grundsätzlich einmal innerhalb von fünf Jahren einen kleinen gesellschaftlich abgesicherten Sofortkredit erhalten."},{"number":303,"title":"Wohnkredit","text":"Für den Erwerb angemessenen selbstgenutzten Wohnraums kann ein einmaliger oder nach Rückzahlung erneut zugänglicher Kredit vorgesehen werden."},{"number":304,"title":"Kredittransparenz","text":"Kreditbedingungen, Risiken und Rückzahlungsregeln müssen verständlich dargestellt werden."},{"number":305,"title":"Bürgerkapital","text":"Jede Person besitzt persönliches Bürgerkapital nach den gesetzlichen Regeln dieses Modells."},{"number":306,"title":"Bürgerkapital-Investition","text":"Ein definierter Anteil des Bürgerkapitals und ein definierter Anteil geeigneter Einkommensbestandteile können in das Bürgerinvestitionssystem fließen."},{"number":307,"title":"Fünf-Prozent-Regel","text":"Der Entwurf sieht zunächst vor, fünf Prozent des Bürgerkapitals und fünf Prozent des dafür vorgesehenen Einkommensanteils für das Investitionssystem vorzusehen."},{"number":308,"title":"Freiwillige Projekte","text":"Bürger entscheiden grundsätzlich selbst, welche zugelassenen Vorhaben sie durch Investitionen unterstützen."},{"number":309,"title":"Kein Gewinnversprechen","text":"Bürgerinvestitionen garantieren keinen Gewinn."},{"number":310,"title":"Risikostreuung","text":"Das System soll eine Streuung über unterschiedliche Vorhaben ermöglichen und Konzentrationsrisiken sichtbar machen."},{"number":311,"title":"Gewinnverwendung","text":"Erträge können reinvestiert, zur Refinanzierung verwendet oder nach den Regeln des Systems ausgezahlt werden."},{"number":312,"title":"Soziale Projekte","text":"Bürgerkapital kann auch Projekte finanzieren, die gesellschaftlich nützlich sind, aber keine gewöhnliche private Rendite erwarten lassen."}]},"VIII":{"title":"Arbeit, Soziales, Daten und Technologie","articles":[{"number":313,"title":"Arbeitsgesellschaft","text":"Arbeit wird als Beitrag zur Gesellschaft anerkannt, ohne den menschlichen Wert an Erwerbsleistung zu knüpfen."},{"number":314,"title":"Arbeitslosigkeit","text":"Arbeitslosigkeit ist kein persönliches Versagen und wird nicht automatisch als Schuld bewertet."},{"number":315,"title":"Vermittlung","text":"Arbeitsvermittlung verbindet freie Stellen, Fähigkeiten und Qualifizierungsangebote."},{"number":316,"title":"Qualifizierung","text":"Wer keine passende Arbeit findet, erhält Zugang zu Qualifizierung und Neuorientierung."},{"number":317,"title":"Gemeinwohlangebote","text":"Gemeinwohlorientierte Arbeit kann angeboten werden, wenn sie sinnvoll, sicher und verhältnismäßig ist."},{"number":318,"title":"Beschäftigungspool","text":"Bei starkem Arbeitsmangel kann ein staatlich koordinierter Beschäftigungspool zeitweise zusätzliche Arbeitsmöglichkeiten vermitteln."},{"number":319,"title":"Unternehmensvermittlung","text":"Geeignete Personen können mit Zustimmung in Unternehmen vermittelt werden, wenn dort zusätzliche Arbeitskräfte benötigt werden."},{"number":320,"title":"Arbeitsrechte","text":"Alle Beschäftigten behalten die allgemeinen Arbeits- und Grundrechte."},{"number":321,"title":"Digitale Identität","text":"Eine sichere digitale Identität darf nur für festgelegte Zwecke verwendet werden."},{"number":322,"title":"Dateneinwilligung","text":"Personenbezogene Daten werden grundsätzlich nur nach verständlicher, zweckgebundener und widerrufbarer Zustimmung verarbeitet, sofern keine eng begrenzte gesetzliche Ausnahme besteht."},{"number":323,"title":"Ausnahmen","text":"Gesetzliche Ausnahmen vom Einwilligungsprinzip müssen konkret begründet, zweckgebunden und kontrollierbar sein."},{"number":324,"title":"Aggregierte Planung","text":"Für gesellschaftliche Planung dürfen erforderliche Daten möglichst anonymisiert oder aggregiert verwendet werden."},{"number":325,"title":"Keine Totalüberwachung","text":"Eine umfassende individuelle Überwachung ohne konkreten gesetzlichen Zweck ist unzulässig."},{"number":326,"title":"Daten-Trennung","text":"Finanz-, Gesundheits-, Bildungs-, Kommunikations- und andere sensible Daten bleiben grundsätzlich getrennt."},{"number":327,"title":"Digitale Kontrollbehörde","text":"Eine unabhängige digitale Kontrollbehörde überwacht Datenschutz, Datennutzung und digitale Grundrechte."},{"number":328,"title":"Technologieprüfung","text":"Technologien, die in kritischen Bereichen eingesetzt werden, werden auf Sicherheits-, Spionage- und Datenabflussrisiken geprüft."},{"number":329,"title":"Ausländische Datenübertragung","text":"Unzulässige Datenübertragung an ausländische Stellen oder Systeme wird verhindert."},{"number":330,"title":"Sichere Technik","text":"Kritische digitale Systeme müssen nachweisbare Sicherheits- und Wiederherstellungsverfahren besitzen."},{"number":331,"title":"Algorithmische Entscheidungen","text":"Automatisierte Entscheidungen mit erheblichen Auswirkungen auf Menschen müssen erklärbar und überprüfbar sein."}]},"IX":{"title":"Justiz, Polizei, Verteidigung, Außenbeziehungen und Umwelt","articles":[{"number":332,"title":"Rechtsstaat","text":"Rechtsprechung ist unabhängig und an Verfassung und Gesetz gebunden."},{"number":333,"title":"Gerichtsorganisation","text":"Gerichte werden nach transparenten gesetzlichen Zuständigkeitsregeln organisiert."},{"number":334,"title":"Richterliche Unabhängigkeit","text":"Richter dürfen bei ihrer Entscheidung keinen politischen Weisungen unterliegen."},{"number":335,"title":"Staatsanwaltschaft","text":"Strafverfolgung erfolgt nach Gesetz und fachlichen Regeln, nicht nach parteipolitischer Weisung."},{"number":336,"title":"Verfassungsgericht","text":"Ein unabhängiges Verfassungsgericht wacht über die Einhaltung der Verfassung."},{"number":337,"title":"Polizeiaufgabe","text":"Die Polizei schützt Menschen, Eigentum, öffentliche Sicherheit und die freiheitliche Ordnung."},{"number":338,"title":"Polizeiliche Verhältnismäßigkeit","text":"Polizeiliche Maßnahmen müssen geeignet, erforderlich und angemessen sein."},{"number":339,"title":"Deeskalation","text":"Polizeiliches Handeln soll Konflikte möglichst deeskalieren und unnötige Gewalt vermeiden."},{"number":340,"title":"Polizeikontrolle","text":"Eine unabhängige Stelle kontrolliert polizeiliches Fehlverhalten und Beschwerden."},{"number":341,"title":"Dokumentation","text":"Schwerwiegende polizeiliche Maßnahmen werden nachvollziehbar dokumentiert."},{"number":342,"title":"Körperkameras","text":"Körperkameras können unter klaren Datenschutz- und Dokumentationsregeln eingesetzt werden."},{"number":343,"title":"Polizeilicher Missbrauch","text":"Absichtlicher Machtmissbrauch wird unabhängig verfolgt; ehrliche Fehler werden von vorsätzlichem Fehlverhalten unterschieden."},{"number":344,"title":"Terrorismus","text":"Der Staat schützt die Bevölkerung vor terroristischer Gewalt und wahrt dabei die gesetzlichen Grenzen."},{"number":345,"title":"Grenzschutz","text":"Grenzen werden nach geltendem Recht geschützt, ohne Menschenwürde und rechtsstaatliche Verfahren aufzugeben."},{"number":346,"title":"Verteidigung","text":"Die Verteidigung dient dem Schutz der Bevölkerung und nicht der Eroberung fremden Gebiets."},{"number":347,"title":"Keine Angriffskriege","text":"Aggressive militärische Gewalt zur Erweiterung politischer oder wirtschaftlicher Macht ist ausgeschlossen."},{"number":348,"title":"Verteidigungsfähigkeit","text":"Die Gesellschaft hält angemessene Fähigkeiten zur Abwehr äußerer Angriffe vor."},{"number":349,"title":"Freiwillige Streitkräfte","text":"Militärische Dienste werden grundsätzlich freiwillig organisiert."},{"number":350,"title":"Zivile Kontrolle","text":"Die Streitkräfte unterstehen demokratischer ziviler Kontrolle."},{"number":351,"title":"Soldatenrechte","text":"Soldatinnen und Soldaten behalten ihre grundlegenden Menschen- und Rechtsrechte."},{"number":352,"title":"Militärrecht","text":"Militärisches Handeln unterliegt Recht, Menschenrechten und den Regeln bewaffneter Konflikte."},{"number":353,"title":"Zivilschutz","text":"Für schwere äußere und innere Krisen bestehen zivile Schutz- und Evakuierungspläne."},{"number":354,"title":"Internationale Zusammenarbeit","text":"Internationale Zusammenarbeit ist zulässig, soweit sie Rechte, Sicherheit und Selbstbestimmung wahrt."},{"number":355,"title":"Außenvertretungen","text":"Ausländische Vertreter können vor zuständigen Gremien angehört werden, besitzen dort aber kein Stimmrecht."},{"number":356,"title":"Internationale Verträge","text":"Internationale Verträge werden auf Souveränität, Rechte, Wirtschaft, Sicherheit und Umweltfolgen geprüft."},{"number":357,"title":"Langfristige Verträge","text":"Grundlegende oder besonders langfristige Bindungen können einer Volksabstimmung unterliegen."},{"number":358,"title":"Außenhandel","text":"Internationaler Handel bleibt grundsätzlich zulässig."},{"number":359,"title":"Auslandshilfe","text":"Staatliche Auslandshilfe darf die langfristige innere wirtschaftliche Tragfähigkeit nicht gefährden."},{"number":360,"title":"Keine ausländische Steuerung","text":"Ausländische Regierungen dürfen keine staatlichen Entscheidungen durch verdeckte Finanzierung oder Abhängigkeit bestimmen."},{"number":361,"title":"Umweltschutz","text":"Natur und Umwelt werden als Grundlage gegenwärtiger und zukünftiger Lebensmöglichkeiten geschützt."},{"number":362,"title":"Intergenerationelle Verantwortung","text":"Heutige Entscheidungen berücksichtigen die Rechte zukünftiger Generationen."},{"number":363,"title":"Klimavorsorge","text":"Infrastruktur und Versorgung werden auf langfristige klimatische Veränderungen und Extremereignisse vorbereitet."}]}};
